const terms = '(banjir OR kebanjiran OR genangan OR "air naik" OR "jalan terendam" OR "sungai meluap" OR "air masuk rumah" OR rob)';
const regions = '(Jakarta OR Bogor OR Depok OR Tangerang OR Tangsel OR "Tangerang Selatan" OR Bekasi OR Jabodetabek)';
const exclusions = '-"banjir diskon" -"banjir order" -"banjir hadiah" -"banjir dukungan"';
const base = `${terms} ${regions} ${exclusions}`;

return [
  { json: { query_group: 'x', q: `${base} site:x.com` } },
  { json: { query_group: 'short_video', q: `${base} (site:tiktok.com OR site:instagram.com)` } },
  { json: { query_group: 'youtube', q: `${base} site:youtube.com` } },
  { json: { query_group: 'web_news', q: `${base} -site:x.com -site:tiktok.com -site:instagram.com -site:youtube.com` } },
];

const positive = ['banjir', 'kebanjiran', 'genangan', 'terendam', 'air naik', 'meluap', 'rob', 'air masuk rumah'];
const impact = ['jalan', 'rumah', 'kendaraan', 'sungai', 'drainase', 'warga', 'evakuasi', 'macet', 'ditutup'];
const negative = ['banjir diskon', 'banjir order', 'banjir hadiah', 'banjir dukungan', 'game', 'film'];
const locations = [
  { aliases: ['kampung melayu', 'kp melayu'], name: 'Kampung Melayu', lat: -6.2245, lng: 106.8662, confidence: 0.65 },
  { aliases: ['bidara cina'], name: 'Bidara Cina', lat: -6.2291, lng: 106.8670, confidence: 0.65 },
  { aliases: ['kelapa gading'], name: 'Kelapa Gading', lat: -6.1588, lng: 106.9056, confidence: 0.65 },
  { aliases: ['cawang'], name: 'Cawang', lat: -6.2451, lng: 106.8753, confidence: 0.65 },
  { aliases: ['pluit'], name: 'Pluit', lat: -6.1265, lng: 106.7904, confidence: 0.65 },
  { aliases: ['penjaringan'], name: 'Penjaringan', lat: -6.1177, lng: 106.7839, confidence: 0.65 },
  { aliases: ['cengkareng'], name: 'Cengkareng', lat: -6.1527, lng: 106.7447, confidence: 0.65 },
  { aliases: ['pesanggrahan'], name: 'Pesanggrahan', lat: -6.2554, lng: 106.7636, confidence: 0.65 },
  { aliases: ['tangerang selatan', 'tangsel'], name: 'Tangerang Selatan', lat: -6.2889, lng: 106.7181, confidence: 0.35 },
  { aliases: ['jakarta'], name: 'DKI Jakarta', lat: -6.2088, lng: 106.8456, confidence: 0.30 },
  { aliases: ['bekasi'], name: 'Bekasi', lat: -6.2383, lng: 106.9756, confidence: 0.35 },
  { aliases: ['depok'], name: 'Depok', lat: -6.4025, lng: 106.7942, confidence: 0.35 },
  { aliases: ['bogor'], name: 'Bogor', lat: -6.5950, lng: 106.8166, confidence: 0.35 },
  { aliases: ['tangerang'], name: 'Tangerang', lat: -6.1783, lng: 106.6319, confidence: 0.35 }
];
const trackingParams = new Set(['gclid', 'fbclid', 'igshid', 'si', 'feature', 'ref', 'ref_src']);

function normalizeUrl(value) {
  try {
    const url = new URL(String(value || '').trim());
    if (!['http:', 'https:'].includes(url.protocol)) return '';
    url.hash = '';
    url.hostname = url.hostname.toLowerCase().replace(/^www\./, '').replace(/^m\.youtube\.com$/, 'youtube.com');
    for (const key of [...url.searchParams.keys()]) {
      if (key.toLowerCase().startsWith('utm_') || trackingParams.has(key.toLowerCase())) url.searchParams.delete(key);
    }
    url.searchParams.sort();
    return url.toString().replace(/\/$/, '').slice(0, 700);
  } catch {
    return '';
  }
}

function platformFromUrl(value) {
  try {
    const host = new URL(value).hostname.replace(/^www\./, '');
    const matches = (domain) => host === domain || host.endsWith(`.${domain}`);
    if (matches('x.com') || matches('twitter.com')) return 'x';
    if (matches('tiktok.com')) return 'tiktok';
    if (matches('instagram.com')) return 'instagram';
    if (matches('youtube.com') || matches('youtu.be')) return 'youtube';
  } catch {}
  return 'web';
}

function jakartaDateTime(date) {
  const parts = Object.fromEntries(new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Jakarta', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23'
  }).formatToParts(date).filter((part) => part.type !== 'literal').map((part) => [part.type, part.value]));
  return `${parts.year}-${parts.month}-${parts.day} ${parts.hour}:${parts.minute}:${parts.second}`;
}

function parsePublishedAt(raw, now) {
  if (!raw) return null;
  const text = String(raw).trim().toLowerCase();
  const relative = [
    { regex: /(\d+)\s*(menit|minute|minutes|min)\s*(lalu|ago)?/, ms: 60000 },
    { regex: /(\d+)\s*(jam|hour|hours)\s*(lalu|ago)?/, ms: 3600000 },
    { regex: /(\d+)\s*(hari|day|days)\s*(lalu|ago)?/, ms: 86400000 }
  ];
  for (const rule of relative) {
    const match = text.match(rule.regex);
    if (match) return jakartaDateTime(new Date(now.getTime() - Number(match[1]) * rule.ms));
  }
  const parsed = Date.parse(raw);
  return Number.isFinite(parsed) ? jakartaDateTime(new Date(parsed)) : null;
}

const inputs = $input.all();
const queryInputs = $('Build Search Queries').all();
const now = new Date();
const collectedAt = jakartaDateTime(now);
const seen = new Set();
const output = [];

for (let inputIndex = 0; inputIndex < inputs.length; inputIndex++) {
  const body = inputs[inputIndex].json.body ?? inputs[inputIndex].json;
  if (body.error) throw new Error(`SerpApi error: ${body.error}`);
  const queryGroup = queryInputs[inputIndex]?.json?.query_group ?? 'unknown';
  const results = [
    ...(Array.isArray(body.organic_results) ? body.organic_results : []),
    ...(Array.isArray(body.news_results) ? body.news_results : []),
    ...(Array.isArray(body.top_stories) ? body.top_stories : [])
  ];

  for (const result of results) {
    const sourceUrl = normalizeUrl(result.link);
    if (!sourceUrl) continue;
    const platform = platformFromUrl(sourceUrl);
    const duplicateKey = `${platform}|${sourceUrl}`;
    if (seen.has(duplicateKey)) continue;

    const text = `${result.title ?? ''} ${result.snippet ?? ''}`.toLowerCase();
    const positiveHits = positive.filter((term) => text.includes(term)).length;
    const negativeHits = negative.filter((term) => text.includes(term)).length;
    if (positiveHits === 0 || negativeHits > 0) continue;

    const matchedLocation = locations.find((loc) => loc.aliases.some((alias) => text.includes(alias)));
    const impactHits = impact.filter((term) => text.includes(term)).length;
    const numericPosition = Number(result.position);
    const position = Number.isFinite(numericPosition) ? numericPosition : null;
    const relevance = Math.min(100, positiveHits * 25 + impactHits * 8 + (matchedLocation ? 20 : 0));
    const rankContribution = position === null ? 0 : Math.max(0, 45 - position);
    const hasVisual = Boolean(result.thumbnail || result.thumbnail_small);
    const discovery = Math.min(100, rankContribution + relevance * 0.35 + (hasVisual ? 15 : 0));
    seen.add(duplicateKey);

    output.push({
      json: {
        platform,
        external_id: sourceUrl,
        source_url: sourceUrl,
        title: result.title ?? null,
        text_content: result.snippet ?? null,
        source_published_text: result.date ?? null,
        published_at: parsePublishedAt(result.date, now),
        collected_at: collectedAt,
        latitude: matchedLocation?.lat ?? null,
        longitude: matchedLocation?.lng ?? null,
        location_name: matchedLocation?.name ?? null,
        location_method: matchedLocation ? 'text_alias' : 'unknown',
        location_confidence: matchedLocation?.confidence ?? 0,
        search_position: position,
        relevance_score: Number(relevance.toFixed(2)),
        discovery_score: Number(discovery.toFixed(2)),
        collection_method: 'serpapi_google',
        raw_payload: JSON.stringify({
          query_group: queryGroup,
          title: result.title ?? null,
          link: result.link ?? null,
          snippet: result.snippet ?? null,
          date: result.date ?? null,
          position,
          displayed_link: result.displayed_link ?? null,
          thumbnail: result.thumbnail ?? result.thumbnail_small ?? null
        })
      }
    });
  }
}

return output;
